122→func (c *CopilotCLI) StartSession(ctx context.Context, dir string) (Session, error) {
123→	bin, err := exec.LookPath(c.Binary())
124→	if err != nil {
125→		return nil, fmt.Errorf("agent binary not found: %w", err)
126→	}
127→
128→	// Forward critical env vars into the tmux session. tmux starts a new
129→	// shell that doesn't inherit Go's os.Environ(), so without this the
130→	// session lacks auth tokens (COPILOT_GITHUB_TOKEN) and HOME (for gh auth).
131→	if os.Getenv("COPILOT_GITHUB_TOKEN") == "" {
132→		return nil, errors.New("COPILOT_GITHUB_TOKEN is not set; copilot-cli interactive session requires authentication")
