136→		if v := os.Getenv(key); v != "" {
137→			envArgs = append(envArgs, key+"="+v)
138→		}
139→	}
140→	args := append([]string{"env"}, envArgs...)
141→	args = append(args, bin, "--model", "gpt-4.1", "--allow-all")
142→
143→	name := fmt.Sprintf("copilot-test-%d", time.Now().UnixNano())
144→	// Strip CI env vars that may affect interactive mode.
145→	unset := []string{"CI", "GITHUB_ACTIONS", "ENTIRE_TEST_TTY"}
146→	s, err := NewTmuxSession(name, dir, unset, args[0], args[1:]...)
147→	if err != nil {
148→		return nil, err
149→	}
150→
151→	// Dismiss startup dialogs (folder trust, etc.) then wait for the "❯" prompt.
152→	// Copilot CLI shows a "Confirm folder trust" dialog in interactive mode for
153→	// new directories. "Yes" is pre-selected, so Enter dismisses it.
154→	foundPrompt := false
155→	for range 5 {
156→		content, err := s.WaitFor(`(❯|Enter to select)`, 30*time.Second)
157→		if err != nil {
158→			_ = s.Close()
159→			return nil, fmt.Errorf("waiting for startup prompt: %w", err)
160→		}
161→		if strings.Contains(content, "❯") && !strings.Contains(content, "Enter to select") {
162→			foundPrompt = true
163→			break
164→		}
165→		if err := s.SendKeys("Enter"); err != nil {
166→			_ = s.Close()
167→			return nil, fmt.Errorf("dismissing startup dialog: %w", err)
168→		}
169→		time.Sleep(500 * time.Millisecond)
170→	}
171→	if !foundPrompt {
172→		_ = s.Close()
173→		return nil, errors.New("copilot CLI did not reach interactive prompt after dismissing startup dialogs")
174→	}
175→	s.stableAtSend = ""
176→
177→	return s, nil
178→}
