  1→// vogon is a deterministic agent binary for E2E canary tests.
  2→// It parses simple prompt instructions, performs file operations, fires
  3→// lifecycle hooks via `entire hooks vogon <verb>`, and writes a minimal
  4→// JSONL transcript. No API calls are made.
  5→//
  6→// Named after the Vogons from The Hitchhiker's Guide to the Galaxy —
  7→// bureaucratic, procedural, and deterministic to a fault.
  8→//
  9→// Usage:
 10→//
 11→//	vogon -p <prompt>   # Headless (single-turn) mode
 12→//	vogon               # Interactive (multi-turn) mode
 13→package main
 14→
 15→import (
 16→	"bufio"
 17→	"bytes"
 18→	"encoding/json"
 19→	"fmt"
 20→	"os"
 21→	"os/exec"
 22→	"path/filepath"
 23→	"regexp"
 24→	"strings"
 25→	"time"
 26→
 27→	"github.com/google/uuid"
 28→)
 29→
 30→func main() {
 31→	prompt := ""
 32→	for i := 1; i < len(os.Args); i++ {
 33→		if os.Args[i] == "-p" && i+1 < len(os.Args) {
 34→			prompt = os.Args[i+1]
 35→			i++
 36→		}
 37→	}
 38→
 39→	dir, err := os.Getwd() //nolint:forbidigo // Standalone binary, not part of CLI — CWD is the repo dir
 40→	if err != nil {
 41→		fatal("getwd: %v", err)
 42→	}
 43→
 44→	sessionID := uuid.New().String()
 45→	transcriptPath := setupTranscript(sessionID)
 46→
 47→	fireHook(dir, "session-start", map[string]string{
 48→		"session_id":      sessionID,
 49→		"transcript_path": transcriptPath,
 50→	})
 51→
 52→	if prompt != "" {
 53→		// Headless mode: single prompt
 54→		runTurn(dir, sessionID, transcriptPath, prompt)
 55→	} else {
 56→		// Interactive mode: read prompts from stdin
 57→		fmt.Fprint(os.Stdout, "> ")
 58→		scanner := bufio.NewScanner(os.Stdin)
 59→		for scanner.Scan() {
 60→			line := strings.TrimSpace(scanner.Text())
 61→			if line == "" || line == "exit" || line == "quit" {
 62→				break
 63→			}
 64→			// Give tmux's Send() time to capture the echoed-input state
 65→			// before we produce any output. Send polls every 200ms; without
 66→			// this pause, vogon output appears in the same capture window
 67→			// as the echo, causing stableAtSend to include final output and
 68→			// preventing WaitFor's contentChanged detection.
 69→			time.Sleep(700 * time.Millisecond)
 70→			fmt.Fprintln(os.Stdout, "Working...")
 71→			runTurn(dir, sessionID, transcriptPath, line)
 72→			fmt.Fprint(os.Stdout, "> ")
 73→		}
 74→	}
 75→
 76→	fireHook(dir, "session-end", map[string]string{
 77→		"session_id":      sessionID,
 78→		"transcript_path": transcriptPath,
 79→	})
 80→}
 81→
 82→func runTurn(dir, sessionID, transcriptPath, prompt string) {
 83→	fireHook(dir, "user-prompt-submit", map[string]any{
 84→		"session_id":      sessionID,
 85→		"transcript_path": transcriptPath,
 86→		"prompt":          prompt,
 87→	})
 88→
 89→	appendTranscript(transcriptPath, "user", prompt)
 90→
 91→	actions := parsePrompt(prompt)
 92→	executeActions(dir, actions)
 93→
 94→	appendTranscript(transcriptPath, "assistant", fmt.Sprintf("Done. Executed %d actions.", len(actions)))
 95→	fmt.Fprintf(os.Stdout, "Done. Executed %d actions.\n", len(actions))
 96→
 97→	fireHook(dir, "stop", map[string]string{
 98→		"session_id":      sessionID,
 99→		"transcript_path": transcriptPath,
100→	})
101→}
