103→// --- Prompt Parsing ---
104→
105→type action struct {
106→	kind    string // "create", "modify", "delete", "commit"
107→	path    string
108→	content string
109→}
110→
111→// fileExt is the shared file extension pattern used across all prompt-parsing regexes.
112→const fileExt = `go|md|txt|js|ts|py|rb|rs|toml|yaml|json`
113→
114→var (
115→	// "create a [single|new|...] [markdown|text] file [at|called] <path>"
116→	createFileRe = regexp.MustCompile(`(?i)create\s+(?:a\s+)?(?:\w+\s+)*?(?:markdown\s+|text\s+)?file\s+(?:at\s+|called\s+)?([^\s,]+\.(?:` + fileExt + `))`)
117→	// "create N files: <path> about <topic>, <path> about <topic>"
118→	createMultiRe = regexp.MustCompile(`(?i)create\s+(?:\w+\s+)*?(?:four|three|two|\d+)\s+(?:\w+\s+)*?(?:markdown\s+)?files?:?\s+(.+)`)
119→	// "modify <path>"
120→	modifyFileRe = regexp.MustCompile(`(?i)modify\s+(?:the\s+)?(?:file\s+)?(?:at\s+)?([^\s,]+\.(?:` + fileExt + `))`)
121→	// "modify [these] N [existing] files[:]"
122→	modifyMultiRe = regexp.MustCompile(`(?i)modify\s+(?:these\s+)?(?:three|four|two|\d+)\s+(?:\w+\s+)*?files?[.:]\s*(.+)`)
123→	// "add ... to <path>" (e.g. "add another stanza to poem.txt")
124→	addToFileRe = regexp.MustCompile(`(?i)add\s+(?:another\s+|a\s+|some\s+)?\w+\s+to\s+([^\s,]+\.(?:` + fileExt + `))`)
125→	// "delete <path>"
126→	deleteFileRe = regexp.MustCompile(`(?i)delete\s+(?:the\s+)?(?:file\s+)?(?:at\s+)?([^\s,]+\.(?:` + fileExt + `))`)
127→	// "commit" anywhere in the prompt, but not "do not commit" / "don't commit"
128→	commitRe = regexp.MustCompile(`(?i)(?:then\s+|now\s+)?(?:git\s+)?commit\b`)
129→	// Negative: "do not commit" / "don't commit" with optional object, at sentence boundary
130→	// Matches: "Do not commit.", "Do not commit the file.", "Do not commit them,"
131→	// Does NOT match: "Do not commit any other files" (different intent)
132→	noCommitRe = regexp.MustCompile(`(?i)(?:do\s+not|don'?t)\s+commit(?:\s+(?:it|them|the\s+\w+))?(?:\.|,|$)`)
133→	// "commit each file separately" — interleave create+commit
134→	commitSeparatelyRe = regexp.MustCompile(`(?i)commit\s+each\s+file\s+separately`)
135→	// Individual file in multi-create: "docs/a.md about apples"
136→	// Topic capture stops at comma, "and", period followed by space+uppercase, or end
137→	multiFileItemRe = regexp.MustCompile(`([^\s,]+\.(?:` + fileExt + `))\s+(?:about\s+|with\s+|containing\s+)?(.+?)(?:,\s*|\s+and\s+|\.\s+[A-Z]|\.\s*$)`)
138→	// Individual file in multi-modify: "src/model.go should define ..."
139→	modifyItemRe = regexp.MustCompile(`([^\s,]+\.(?:` + fileExt + `))\s+should\s+(.+?)(?:,|$)`)
140→	// "In src/a.go, add ..." pattern for multi-modify
141→	inFileRe = regexp.MustCompile(`[Ii]n\s+([^\s,]+\.(?:` + fileExt + `))`)
142→	// Inline content: "with content 'package main; func Foo() {}'"
143→	inlineContentRe = regexp.MustCompile(`(?i)with\s+content\s+['"]([^'"]+)['"]`)
144→	// Numbered steps: "(1) ... (2) ... (3) ..."
145→	numberedStepRe = regexp.MustCompile(`\(\d+\)\s+`)
146→	// Explicit git command: "Run: git add ... && git commit -m '...'"
147→	explicitGitRe = regexp.MustCompile(`(?i)run:?\s+git\s+add\s+.+(?:&&\s*git\s+commit|;\s*git\s+commit)`)
148→	// "about the colour red" → "the colour red"
149→	topicRe = regexp.MustCompile(`(?i)about\s+(.+?)(?:\.|,|\s+Do\s|\s+do\s|\s+then\s|$)`)
150→	// Fallback: extract any file path from text
151→	anyFileRe = regexp.MustCompile(`([^\s,]+\.(?:` + fileExt + `))`)
152→)
153→
154→func parsePrompt(prompt string) []action {
155→	// Check for numbered-step prompts — parse each step independently to
156→	// preserve ordering (e.g., create, commit, then create more).
157→	if numberedStepRe.MatchString(prompt) {
158→		return parseNumberedSteps(prompt)
159→	}
160→	var actions []action
161→
162→	// Multi-file modify: "modify these three files: src/model.go should ..., src/view.go should ..."
163→	// Also matches: "Modify two existing files. In src/a.go, add ..."
164→	if m := modifyMultiRe.FindStringSubmatch(prompt); m != nil {
165→		// Try "should" pattern first
166→		items := modifyItemRe.FindAllStringSubmatch(m[1], -1)
167→		for _, item := range items {
168→			actions = append(actions, action{
169→				kind:    "modify",
170→				path:    item[1],
171→				content: "// " + strings.TrimSpace(item[2]) + "\n",
172→			})
173→		}
174→		// Try "In <path>" pattern as fallback
175→		if len(actions) == 0 {
176→			for _, item := range inFileRe.FindAllStringSubmatch(m[1], -1) {
177→				actions = append(actions, action{
178→					kind:    "modify",
179→					path:    item[1],
180→					content: "// Modified by vogon agent\n",
181→				})
182→			}
183→		}
184→		// Last resort: extract any file paths
185→		if len(actions) == 0 {
186→			for _, fm := range anyFileRe.FindAllStringSubmatch(m[1], -1) {
187→				actions = append(actions, action{
188→					kind:    "modify",
189→					path:    fm[1],
190→					content: "// Modified by vogon agent\n",
191→				})
192→			}
193→		}
194→	}
195→
196→	// Multi-file create: "create four markdown files: docs/a.md about apples, ..."
197→	if len(actions) == 0 || hasModifyOnly(actions) {
198→		if m := createMultiRe.FindStringSubmatch(prompt); m != nil {
199→			items := multiFileItemRe.FindAllStringSubmatch(m[1], -1)
200→			for _, item := range items {
201→				actions = append(actions, action{
202→					kind:    "create",
203→					path:    item[1],
204→					content: fmt.Sprintf("# %s\n\nA paragraph about %s.\n", strings.TrimSpace(item[2]), strings.TrimSpace(item[2])),
205→				})
206→			}
207→		}
208→	}
209→
210→	// Single file create — also runs if we only have modifies (combined prompts)
211→	if !hasCreate(actions) {
212→		if m := createFileRe.FindStringSubmatch(prompt); m != nil {
213→			topic := extractTopic(prompt)
214→			content := fmt.Sprintf("# %s\n\nA paragraph about %s.\n", topic, topic)
215→			if ic := inlineContentRe.FindStringSubmatch(prompt); ic != nil {
216→				content = ic[1] + "\n"
217→			}
218→			actions = append(actions, action{
219→				kind:    "create",
220→				path:    m[1],
221→				content: content,
222→			})
223→		}
224→	}
225→
226→	// Single file modify — also runs if we only have creates (combined prompts)
227→	if !hasModify(actions) {
228→		if m := modifyFileRe.FindStringSubmatch(prompt); m != nil {
229→			actions = append(actions, action{
230→				kind:    "modify",
231→				path:    m[1],
232→				content: "// Modified by vogon agent\n",
233→			})
234→		}
235→	}
236→
237→	// "add ... to <path>" as modify (e.g. "add another stanza to poem.txt")
238→	if !hasModify(actions) {
239→		if m := addToFileRe.FindStringSubmatch(prompt); m != nil {
240→			actions = append(actions, action{
241→				kind:    "modify",
242→				path:    m[1],
243→				content: "// Modified by vogon agent\n",
244→			})
245→		}
246→	}
247→
248→	// Delete
249→	if m := deleteFileRe.FindStringSubmatch(prompt); m != nil {
250→		actions = append(actions, action{kind: "delete", path: m[1]})
251→	}
252→
253→	// Commit: check for "commit each file separately" (interleaved) vs normal.
254→	// Skip if prompt contains "do not commit" / "don't commit".
255→	if !noCommitRe.MatchString(prompt) {
256→		if commitSeparatelyRe.MatchString(prompt) {
257→			actions = interleaveCommits(actions)
258→		} else if commitRe.MatchString(prompt) {
259→			actions = append(actions, action{kind: "commit"})
260→		}
261→	}
262→
263→	return actions
264→}
265→
266→// parseNumberedSteps splits "(1) ... (2) ... (3) ..." prompts into individual
267→// steps and parses each one, preserving ordering. This handles prompts like:
268→// "(1) Create file A. (2) Create file B. (3) git commit. (4) Create file C."
269→func parseNumberedSteps(prompt string) []action {
270→	// Split on numbered markers: "(1) ", "(2) ", etc.
271→	indices := numberedStepRe.FindAllStringIndex(prompt, -1)
272→	if len(indices) == 0 {
273→		return nil
274→	}
275→
276→	var steps []string
277→	for i, idx := range indices {
278→		start := idx[1] // after the "(N) " marker
279→		var end int
280→		if i+1 < len(indices) {
281→			end = indices[i+1][0]
282→		} else {
